/**
 * Equivalent of `shutil.get_terminal_size()`, which argparse consults to pick
 * its help width.
 *
 * CPython's precedence, mirrored here:
 *   1. the COLUMNS / LINES environment variables, when they parse as integers
 *      (a non-positive or unparseable value falls through);
 *   2. the real terminal size of stdout;
 *   3. the (80, 24) fallback — which is what happens whenever stdout is a pipe,
 *      so redirected runs are reproducible.
 */
import { pyInt } from './int.mjs';

const FALLBACK_COLUMNS = 80;
const FALLBACK_LINES = 24;

function fromEnv(name) {
  const raw = process.env[name];
  if (raw === undefined) return null;
  // CPython calls int(), so surrounding whitespace, a sign, underscores and
  // non-ASCII decimal digits are all accepted; anything else is ignored.
  try {
    return pyInt(raw);
  } catch {
    return null;
  }
}

export function getTerminalSize(fallback = [FALLBACK_COLUMNS, FALLBACK_LINES]) {
  let [columns, lines] = fallback;

  const envColumns = fromEnv('COLUMNS');
  const envLines = fromEnv('LINES');

  if (envColumns === null || envLines === null) {
    if (process.stdout.isTTY) {
      if (typeof process.stdout.columns === 'number' && process.stdout.columns > 0) {
        columns = process.stdout.columns;
      }
      if (typeof process.stdout.rows === 'number' && process.stdout.rows > 0) {
        lines = process.stdout.rows;
      }
    }
  }

  if (envColumns !== null && envColumns > 0) columns = envColumns;
  if (envLines !== null && envLines > 0) lines = envLines;

  return { columns, lines };
}
