 * Node ships no `unicodedata`, so the Wide/Fullwidth code point ranges are
 * listed here. The table covers the East Asian blocks (CJK, kana, Hangul,
 * fullwidth forms) plus the wide emoji blocks; characters outside it count as
 * width 1, which is also the correct answer for every character in this
 * program's own source line.
 */
const WIDE_RANGES = [
  [0x1100, 0x115f], // Hangul Jamo initial consonants
  [0x2e80, 0x303e], // CJK radicals, Kangxi, CJK symbols and punctuation
  [0x3041, 0x33ff], // kana, Bopomofo, Hangul compatibility, CJK compatibility
  [0x3400, 0x4dbf], // CJK Unified Ideographs Extension A
  [0x4e00, 0x9fff], // CJK Unified Ideographs
  [0xa000, 0xa4cf], // Yi
  [0xa960, 0xa97f], // Hangul Jamo Extended-A
  [0xac00, 0xd7a3], // Hangul syllables
  [0xf900, 0xfaff], // CJK compatibility ideographs
  [0xfe10, 0xfe19], // vertical forms
  [0xfe30, 0xfe6b], // CJK compatibility forms, small form variants
  [0xff01, 0xff60], // fullwidth ASCII variants
  [0xffe0, 0xffe6], // fullwidth signs
  [0x17000, 0x18cd5], // Tangut
  [0x1b000, 0x1b2fb], // kana supplement / extended
  [0x1f300, 0x1f64f], // pictographs and emoticons
  [0x1f680, 0x1f6ff], // transport symbols
  [0x1f900, 0x1f9ff], // supplemental symbols and pictographs
  [0x20000, 0x3fffd], // CJK Unified Ideographs Extensions B and beyond
];

/** True when the code point renders double width (East_Asian_Width W or F). */
function isWide(cp) {
  return WIDE_RANGES.some(([low, high]) => cp >= low && cp <= high);
}

/** Total display width of `s`, counting wide characters as two columns. */
export function displayWidth(s) {
  let width = 0;
  for (const ch of s) width += isWide(ch.codePointAt(0)) ? 2 : 1;
  return width;
}

/**
 * CPython's `_byte_offset_to_character_offset`: how many characters the first
 * `offset` UTF-8 bytes of `s` decode to, with invalid tails replaced.
 *
 * The compiled column offsets in a code object are byte offsets, so this is how
 * a traceback maps them back onto a possibly non-ASCII source line.
 */
export function byteOffsetToCharOffset(s, offset) {
  const bytes = Buffer.from(s, 'utf8');
  return Array.from(bytes.subarray(0, offset).toString('utf8')).length;
}

