import { spawnSync } from 'node:child_process';

const REF = process.env.REF_PATH || '/tmp/hw/test4.mjs';
const PORT = process.env.PORT_PATH || '/output/test4.mjs';

function norm(buf) {
  // ONLY the pid in the PYI tag is legitimately variable.
  return buf.toString('binary').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-P:ERROR]');
}

export function runCase(c) {
  const cwd = c.cwd || '/tmp/hw';
  const env = { ...process.env, ...(c.env || {}) };
  for (const k of Object.keys(c.env || {})) if (c.env[k] === null) delete env[k];
  const opts = { cwd, env, encoding: 'buffer', input: c.stdin ?? '' };
  const a = spawnSync(c.ref ?? REF, c.argv, opts);
  const b = spawnSync('node', [PORT, ...c.argv], opts);
  const problems = [];
  if (a.status !== b.status) problems.push(`EXIT ref=${a.status} port=${b.status}`);
  const ao = norm(a.stdout), bo = norm(b.stdout);
  const ae = norm(a.stderr), be = norm(b.stderr);
  if (ao !== bo) problems.push(`STDOUT\n  ref=${JSON.stringify(ao)}\n  port=${JSON.stringify(bo)}`);
  if (ae !== be) problems.push(`STDERR\n  ref=${JSON.stringify(ae)}\n  port=${JSON.stringify(be)}`);
  return { problems, a: { code: a.status, out: ao, err: ae }, b: { code: b.status, out: bo, err: be } };
}

if (import.meta.url === `file://${process.argv[1]}`) {
