#!/usr/bin/env node
/* Parallel byte-exact differential harness. */
import { spawn } from 'node:child_process';

const REF = process.env.REF_PATH || '/tmp/hw/test4.mjs';
const PORT = process.env.PORT_PATH || '/output/test4.mjs';
const CONC = Number(process.env.CONC || 24);

function norm(buf) {
  return buf.toString('binary').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-P:ERROR]');
}

function exec(cmd, args, { cwd, env, stdio }) {
  return new Promise(res => {
    const p = spawn(cmd, args, { cwd, env, stdio: stdio || ['pipe', 'pipe', 'pipe'] });
    const out = [], err = [];
    p.stdout && p.stdout.on('data', d => out.push(d));
    p.stderr && p.stderr.on('data', d => err.push(d));
    p.stdin && p.stdin.end();
    p.on('close', code => res({ code, out: norm(Buffer.concat(out)), err: norm(Buffer.concat(err)) }));
    p.on('error', e => res({ code: -1, out: '', err: 'SPAWNERR ' + e.message }));
  });
}

export async function runCase(c) {
  const cwd = c.cwd || '/tmp/hw';
  const env = { ...process.env, ...(c.env || {}) };
  for (const k of Object.keys(c.env || {})) if (c.env[k] === null || c.env[k] === undefined) delete env[k];
  const a = await exec(c.ref ?? REF, c.argv, { cwd, env });
  const b = await exec('node', [PORT, ...c.argv], { cwd, env });
  const problems = [];
  if (a.code !== b.code) problems.push(`EXIT ref=${a.code} port=${b.code}`);
  if (a.out !== b.out) problems.push(`STDOUT\n  ref =${JSON.stringify(a.out)}\n  port=${JSON.stringify(b.out)}`);
  if (a.err !== b.err) problems.push(`STDERR\n  ref =${JSON.stringify(a.err)}\n  port=${JSON.stringify(b.err)}`);
  return { problems, a, b };
}

export async function runAll(cases, label = '') {
  let pass = 0;
  const fails = [];
  let idx = 0;
  async function worker() {
    while (idx < cases.length) {
      const i = idx++;
      const c = cases[i];
      const r = await runCase(c);
      if (r.problems.length === 0) pass++;
      else fails.push({ c, problems: r.problems });
    }
  }
  await Promise.all(Array.from({ length: CONC }, worker));
  console.log(`${label} pass ${pass}/${cases.length}`);
  for (const f of fails) {
    console.log(`FAIL ${f.c.label || ''} argv=${JSON.stringify(f.c.argv)} env=${JSON.stringify(f.c.env || {})} cwd=${f.c.cwd || '/tmp/hw'}`);
    for (const p of f.problems) console.log(`   ${p}`);
  }
  return fails;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const cases = JSON.parse(process.argv[2]);
  const fails = await runAll(cases);
  process.exitCode = fails.length ? 1 : 0;
}

